begin;
create table public.sm_personal_owners(member_id uuid primary key references public.sm_members(id));
insert into public.sm_personal_owners(member_id) select m.id from public.sm_members m join public.sm_projects p on p.id=m.project_id where p.slug='darayi' and m.name='رضا افشار' and m.title='مدیر پروژه' and m.active;
create function sm_private.personal_member() returns uuid language sql stable security definer set search_path='' as $$select m.id from public.sm_personal_owners o join public.sm_members m on m.id=o.member_id where m.user_id=auth.uid() and m.active limit 1$$;
create table public.sm_personal_projects(id uuid primary key default gen_random_uuid(),owner_member_id uuid not null default sm_private.personal_member() references public.sm_members(id),name text not null check(length(trim(name)) between 1 and 120),created_at timestamptz not null default now(),unique(owner_member_id,name));
create table public.sm_personal_tasks(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.sm_personal_projects(id),title text not null check(length(trim(title)) between 1 and 200),description text not null default '' check(length(description)<=10000),due date,done boolean not null default false,deleted boolean not null default false,revision integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),completed_at timestamptz);
create index on public.sm_personal_tasks(project_id,due);
create function sm_private.personal_project(p uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.sm_personal_projects where id=p and owner_member_id=sm_private.personal_member())$$;
alter table public.sm_personal_owners enable row level security;
alter table public.sm_personal_projects enable row level security;
alter table public.sm_personal_tasks enable row level security;
create policy personal_owner_read on public.sm_personal_owners for select to authenticated using(member_id=sm_private.personal_member());
create policy personal_project_read on public.sm_personal_projects for select to authenticated using(owner_member_id=sm_private.personal_member());
create policy personal_project_insert on public.sm_personal_projects for insert to authenticated with check(owner_member_id=sm_private.personal_member());
create policy personal_project_update on public.sm_personal_projects for update to authenticated using(owner_member_id=sm_private.personal_member()) with check(owner_member_id=sm_private.personal_member());
create policy personal_task_read on public.sm_personal_tasks for select to authenticated using(sm_private.personal_project(project_id));
create policy personal_task_insert on public.sm_personal_tasks for insert to authenticated with check(sm_private.personal_project(project_id));
create policy personal_task_update on public.sm_personal_tasks for update to authenticated using(sm_private.personal_project(project_id)) with check(sm_private.personal_project(project_id));
revoke all on public.sm_personal_owners,public.sm_personal_projects,public.sm_personal_tasks from anon,authenticated;
grant select on public.sm_personal_owners,public.sm_personal_projects,public.sm_personal_tasks to authenticated;
grant insert(name),update(name) on public.sm_personal_projects to authenticated;
grant insert(project_id,title,description,due),update(title,description,due,done,deleted,revision) on public.sm_personal_tasks to authenticated;
create function sm_private.personal_task_revision() returns trigger language plpgsql set search_path='' as $$begin if new.revision<>old.revision+1 then raise exception 'Conflict: refresh and retry';end if;new.updated_at:=now();new.completed_at:=case when new.done and not old.done then now() when not new.done then null else old.completed_at end;return new;end$$;
create trigger personal_task_revision before update on public.sm_personal_tasks for each row execute function sm_private.personal_task_revision();
revoke execute on function sm_private.personal_member(),sm_private.personal_project(uuid),sm_private.personal_task_revision() from public,anon,authenticated;
grant execute on function sm_private.personal_member(),sm_private.personal_project(uuid) to authenticated;
insert into public.sm_personal_projects(owner_member_id,name) select o.member_id,n from public.sm_personal_owners o cross join (values('خواجه نصیر'),('نهاجا'),('بابل'),('بیمارستان اندیکا'),('مجتمع قضایی اهواز'),('سایر موارد و پروژه‌ها')) names(n);
commit;
select count(*) as personal_projects_created from public.sm_personal_projects;
